html=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#123b6d"><title>8760 HOURS</title><link rel="manifest" href="manifest.webmanifest"><link rel="stylesheet" href="styles-v100.css"></head><body><header><b>8760 HOURS</b><nav><a href="#/home">Home</a><a href="#/review">Review</a><a href="#/plan">Plan</a><a href="#/calendar">Calendar</a><a href="#/history">History</a></nav><span id="saveState">Saved</span></header><main id="app"></main><nav class="bottom"><a href="#/home">⌂<small>Home</small></a><a href="#/review">▣<small>Review</small></a><a href="#/plan">□<small>Plan</small></a><a href="#/calendar">▦<small>Calendar</small></a><a href="#/history">◷<small>History</small></a></nav><script type="module" src="app-v100.js"></script></body></html>'''
css=r''':root{--navy:#123b6d;--blue:#0878df;--pale:#dff0ff;--line:#c8d0dc;--bg:#f4f6f8;--text:#122033}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px system-ui,Segoe UI,Arial,sans-serif}header{height:52px;background:var(--navy);color:#fff;display:flex;align-items:center;padding:0 18px;gap:26px;position:sticky;top:0;z-index:10}header b{font-size:20px}header nav{display:flex;gap:4px;flex:1}header a{color:#fff;text-decoration:none;padding:9px 13px;border-radius:4px}header a:hover{background:#185394}#saveState{font-size:12px}main{max-width:1120px;margin:auto;padding:16px 16px 90px}.card{background:#fff;border:1px solid var(--line);border-radius:6px;padding:14px;margin-bottom:12px}.title{font-size:24px;font-weight:750;margin:0 0 12px}.sub{color:#5d6875;font-size:12px}.btn{border:1px solid #aab7c7;background:#fff;border-radius:5px;padding:9px 13px;font-weight:650;cursor:pointer}.btn.primary{background:var(--blue);color:white;border-color:var(--blue)}.grid2{display:grid;grid-template-columns:1fr 1fr;gap:12px}.progress{height:8px;border-radius:5px;background:#d9dee5;overflow:hidden}.progress i{display:block;height:100%;background:var(--blue)}.areaRow,.row{display:flex;align-items:center;gap:9px;padding:7px 4px;border-bottom:1px solid #e4e8ed}.areaRow button{margin-left:auto}.sectionTitle{background:var(--pale);color:#0d3966;padding:6px 8px;font-weight:750;margin:14px 0 8px}.rating{display:flex;gap:7px;align-items:center;flex-wrap:wrap}.rating button{width:38px;height:34px;background:white;border:1px solid #aeb9c6;border-radius:5px}.rating button.active{background:var(--blue);color:#fff}label.q{display:block;font-weight:700;margin:13px 0 5px}textarea,input[type=text]{width:100%;border:1px solid #aeb9c6;border-radius:5px;padding:9px;font:inherit;background:#fff}textarea{min-height:74px;resize:vertical}.tabs{display:flex;gap:5px;overflow:auto;margin-bottom:12px}.tabs button{min-width:70px;padding:7px;border:1px solid #bdc6d0;background:#fff}.tabs button.active{background:var(--blue);color:#fff}.actions{position:sticky;bottom:70px;display:flex;gap:8px;background:#fff;border:1px solid var(--line);padding:8px;margin-top:14px}.actions .next{margin-left:auto}.bottom{display:none}.muted{color:#657181}.danger{color:#9d2222}.calendarRow{display:grid;grid-template-columns:65px 300px 1fr;border-bottom:1px solid var(--line);background:#fff}.month{background:var(--pale);font-weight:800;padding:12px}.mini{font-size:10px;padding:6px;white-space:pre;font-family:ui-monospace,monospace}.monthNote{border:0;border-left:1px solid var(--line);border-radius:0;min-height:78px}.checklist .row span:first-child{width:20px}.pill{font-size:11px;border-radius:12px;padding:3px 7px;background:#e1f1ff;color:#14508a}.history .row{justify-content:space-between}.sys{font-family:ui-monospace,monospace;font-size:12px}.toast{position:fixed;right:15px;bottom:20px;background:#173e6e;color:#fff;padding:10px 14px;border-radius:5px;z-index:50}@media(max-width:700px){header{height:48px;padding:0 12px}header nav{display:none}header b{font-size:17px}main{padding:12px 10px 92px}.grid2{grid-template-columns:1fr}.title{font-size:21px}.bottom{position:fixed;z-index:20;display:grid;grid-template-columns:repeat(5,1fr);bottom:0;left:0;right:0;background:#fff;border-top:1px solid #bbc5d0;padding-bottom:env(safe-area-inset-bottom)}.bottom a{text-decoration:none;color:#183758;text-align:center;padding:8px 2px;font-size:16px}.bottom small{display:block;font-size:10px}.actions{bottom:61px}.calendarRow{grid-template-columns:56px 1fr}.calendarRow .monthNote{grid-column:1/3;border-left:0;border-top:1px solid var(--line);min-height:62px}.mini{font-size:9px}.card{padding:11px}}'''
db=r'''export const DB_NAME='Hours8760DB', DB_VERSION=1; const stores=['metadata','settings','reviews','reviewSections','areaReviews','responses','annualPlans','idealFutureResponses','majorGoals','goalMetrics','goalUncertainties','goalSubprojects','calendarYears','calendarNotes','recoverySnapshots','operationJournal'];
export function openDB(){return new Promise((res,rej)=>{const r=indexedDB.open(DB_NAME,DB_VERSION);r.onupgradeneeded=()=>{const d=r.result;for(const s of stores)if(!d.objectStoreNames.contains(s)){let o=d.createObjectStore(s,{keyPath:s==='calendarYears'?'year':s==='metadata'||s==='settings'?'key':'id'});if(s==='reviews'){o.createIndex('type','type');o.createIndex('status','status');o.createIndex('referenceDate','referenceDate');o.createIndex('periodKey','periodKey')}if(s==='areaReviews'){o.createIndex('reviewId','reviewId');o.createIndex('areaId','areaId');o.createIndex('reviewAreaKey','reviewAreaKey',{unique:true})}if(s==='responses'){o.createIndex('reviewId','reviewId');o.createIndex('questionId','questionId');o.createIndex('reviewQuestionKey','reviewQuestionKey',{unique:true})}if(s==='reviewSections')o.createIndex('reviewId','reviewId');if(s==='calendarNotes')o.createIndex('yearMonthKey','yearMonthKey',{unique:true});}}};r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
const req=(r)=>new Promise((res,rej)=>{r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)});export async function get(store,key){const d=await openDB(),t=d.transaction(store),v=await req(t.objectStore(store).get(key));d.close();return v} export async function all(store){const d=await openDB(),t=d.transaction(store),v=await req(t.objectStore(store).getAll());d.close();return v} export async function put(store,obj){const d=await openDB(),t=d.transaction(store,'readwrite');await req(t.objectStore(store).put(obj));await new Promise((res,rej)=>{t.oncomplete=res;t.onerror=()=>rej(t.error);t.onabort=()=>rej(t.error)});d.close();const back=await get(store,obj[store==='calendarYears'?'year':store==='metadata'||store==='settings'?'key':'id']);if(!back)throw Error('Read-back verification failed');return back} export async function del(store,key){const d=await openDB(),t=d.transaction(store,'readwrite');t.objectStore(store).delete(key);await new Promise((res,rej)=>{t.oncomplete=res;t.onerror=()=>rej(t.error)});d.close()} export async function health(){const d=await openDB();const missing=stores.filter(s=>!d.objectStoreNames.contains(s));const ver=d.version;d.close();return {name:DB_NAME,version:ver,stores:stores.length,missing}} export const uid=()=>crypto.randomUUID();
'''
qs=r'''export const AREAS=[['values_purpose','Values & Purpose'],['contribution_impact','Contribution & Impact'],['location_tangibles','Location & Tangibles'],['money_finances','Money & Finances'],['career_work','Career & Work'],['health_fitness','Health & Fitness'],['education_skills','Education & Skills'],['social_relationships','Social & Relationships'],['emotions_wellbeing','Emotions & Well-Being'],['character_identity','Character & Identity'],['productivity_organization','Productivity & Organization'],['adventure_creativity','Adventure & Creativity']];
const H=[['hamming.most_important_problem','What is the most important problem here?'],['hamming.biggest_bottleneck','What is my biggest bottleneck?'],['hamming.holding_back_potential','What is most holding me back from achieving my full potential?'],['hamming.highest_impact_action','What single thing, if successfully performed, would have the biggest impact here?']];
const Q={values_purpose:[['values_purpose.purpose','Do I have a sense of purpose and direction in life?'],['values_purpose.want','What do I want out of life?'],['values_purpose.world','How do I want the world to be different?'],['values_purpose.philosophy','What is my philosophy of life?'],['values_purpose.values','What are my fundamental values?']],contribution_impact:[['contribution_impact.value','How am I giving value to the world?'],['contribution_impact.difference','Am I making a difference?'],['contribution_impact.causes','Am I contributing to important and worthy causes that I care about?']],location_tangibles:[['location_tangibles.sufficiency','Do I have material sufficiency?'],['location_tangibles.home','Where is home?'],['location_tangibles.living','What is my living situation like?'],['location_tangibles.clutter','Do I have too many things or unnecessary clutter?']],money_finances:[['money_finances.savings','Do I have savings and an emergency fund?'],['money_finances.assets','What is the status of my assets and investments?'],['money_finances.spending','Do I know where my money goes?'],['money_finances.organised','Are my finances organised?'],['money_finances.debt','Do I have any unwanted debt?']],career_work:[['career.income_source','How do I make my money?'],['career.work_description','What do I do? What is my position, role and where do I work?'],['career.mastery_control_purpose','Does my career give me mastery, control and purpose?'],['career.engagement','Am I engaged?'],['career.industry_positioning','Am I well positioned and connected within my industry?'],['career.stress','How stressful is my career or work?']],health_fitness:[['health.typical_food','What do I typically eat?'],['health.energy','Am I generally tired or alert?'],['health.exercise','Do I exercise, what form and how often?'],['health.sleep_duration','How much do I sleep on average?'],['health.sleep_quality','Am I getting good-quality sleep?'],['health.family_risks','Are there health risks that run in my family?']],education_skills:[['education.status','What is my current education status?'],['education.learning','Am I spending time learning new things and developing my mind?'],['education.skills','What are my talents and skills?'],['education.future_skills','What talents and skills do I plan to develop?']],social_relationships:[['social.home_life','How is my home life?'],['social.family','How are my relationships with family members?'],['social.friend','Am I a good friend?'],['social.circles','How large and healthy are my social circles?']],emotions_wellbeing:[['wellbeing.life','How do I feel about my life?'],['wellbeing.enjoying','Am I enjoying life?'],['wellbeing.state','Am I aware of my current emotional state?'],['wellbeing.mindfulness','Do I have a regular mindfulness practice?'],['wellbeing.compassion','Do I practise self-compassion?']],character_identity:[['character.identity','What identity do I have?'],['character.strengths','What are my key strengths?'],['character.weaknesses','What are my key weaknesses?'],['character.virtues','What are my greatest virtues?'],['character.vices','What are my greatest vices?']],productivity_organization:[['productivity.systems_tools','What productivity systems and tools do I use?'],['productivity.organization','Am I organised?'],['productivity.routines','What are my routines and rituals?'],['productivity.deep_work','Am I doing any Deep Work?'],['productivity.priority_clarity','Am I busy because I lack clear priorities?'],['productivity.workspace_setup','Do I have an effective workspace setup?']],adventure_creativity:[['adventure.experience','Am I experiencing what I want to experience in life?'],['adventure.fun','What fun things have I done lately?'],['adventure.creative','What creative things have I done lately?'],['adventure.hobbies','What are my hobbies?']]}; export const questions=(area)=>Q[area]||[]; export const hamming=()=>H; export const areaName=id=>AREAS.find(a=>a[0]===id)?.[1]||id;'''
app=r'''import {openDB,all,get,put,health,uid} from './hours-db-v100.js';import {AREAS,questions,hamming,areaName} from './question-set-v1.js';const A=document.querySelector('#app'), S=document.querySelector('#saveState');let timers=new Map();const now=()=>new Date().toISOString();const esc=s=>(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));async function save(store,obj){S.textContent='Saving…';try{obj.updatedAt=now();obj.revision=(obj.revision||0)+1;await put(store,obj);S.textContent='Saved'}catch(e){S.textContent='Save failed';throw e}}function debounce(k,fn){clearTimeout(timers.get(k));timers.set(k,setTimeout(fn,700))}function bindText(sel,store,rec,field){document.querySelector(sel)?.addEventListener('input',e=>{rec[field]=e.target.value;debounce(store+rec.id+field,()=>save(store,rec))})}const route=()=>location.hash.slice(1)||'/home';async function currentReview(){let r=(await all('reviews')).filter(x=>x.status!=='completed'&&x.status!=='archived').sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt))[0];return r}async function createAnnual(){let y=new Date().getFullYear(),id=uid(),r={id,type:'annual',periodKey:String(y),referenceDate:new Date().toLocaleDateString('en-CA'),title:`${y} Annual Review`,status:'draft',frameworkVersion:1,questionSetVersion:1,reviewTemplateVersion:1,createdAt:now(),updatedAt:now(),revision:0};await put('reviews',r);for(const [areaId] of AREAS)await put('areaReviews',{id:uid(),reviewId:id,areaId,reviewAreaKey:id+':'+areaId,rating:null,summary:'',strengths:'',weaknesses:'',importantProblem:'',biggestBottleneck:'',highestImpactAction:'',ideasForLater:'',completionState:'not_started',createdAt:now(),updatedAt:now(),revision:0});location.hash='/review/'+id+'/area/career_work'}async function home(){let r=await currentReview();let areas=r?(await all('areaReviews')).filter(x=>x.reviewId===r.id):[];let done=areas.filter(x=>['reviewed','no_material_change','skipped_intentionally'].includes(x.completionState)).length;A.innerHTML=`<h1 class=title>Home</h1>${r?`<div class=grid2><section class=card><h2>${esc(r.title)} <span class=pill>In progress</span></h2><p>${done} of 12 areas reviewed</p><div class=progress><i style="width:${done/12*100}%"></i></div><p><button class="btn primary" id=continue>Continue review →</button></p><small class=muted>Saved locally in IndexedDB</small></section><section class=card><b>Life areas</b>${areas.map(x=>`<div class=areaRow><span>${x.completionState==='reviewed'?'☑':'☐'}</span>${areaName(x.areaId)}<button class=btn data-area="${x.areaId}">Open</button></div>`).join('')}</section></div>`:`<section class=card><h2>Plan the next 8,760 hours</h2><p>Create a structured review of your life and preserve it as a dated snapshot.</p><button id=newAnnual class="btn primary">Start Annual Review</button></section>`}<section class=card><button id=sys class=btn>System Check</button></section>`;document.querySelector('#newAnnual')?.addEventListener('click',createAnnual);document.querySelector('#continue')?.addEventListener('click',()=>location.hash='/review/'+r.id+'/area/career_work');document.querySelectorAll('[data-area]').forEach(b=>b.onclick=()=>location.hash='/review/'+r.id+'/area/'+b.dataset.area);document.querySelector('#sys').onclick=systemCheck}async function reviewLanding(){let r=await currentReview();if(!r){A.innerHTML=`<h1 class=title>Review</h1><div class=card><button id=n class="btn primary">Start Annual Review</button></div>`;document.querySelector('#n').onclick=createAnnual;return}let areas=(await all('areaReviews')).filter(x=>x.reviewId===r.id);A.innerHTML=`<h1 class=title>${esc(r.title)}</h1><p class=sub>${esc(r.referenceDate)} · ${esc(r.status)}</p><div class=grid2><section class="card checklist"><div class=sectionTitle>Snapshot</div><div class=row><span>☑</span> Initial overview</div><div class=row><span>☑</span> Present reality</div><div class=sectionTitle>Twelve Life Areas</div>${areas.map((x,i)=>`<div class=row><span>${x.completionState==='reviewed'?'☑':'☐'}</span><a href="#/review/${r.id}/area/${x.areaId}">${String(i+1).padStart(2,'0')} ${areaName(x.areaId)}</a></div>`).join('')}</section><section class="card checklist"><div class=sectionTitle>Future</div>${['Ideal future','Year theme','Focus areas','Major goals'].map(x=>`<div class=row><span>☐</span>${x}</div>`).join('')}<div class=sectionTitle>Optimise</div>${['Success measures','Uncertainties','Compact calendar'].map(x=>`<div class=row><span>☐</span>${x}</div>`).join('')}<div class=sectionTitle>Finish</div>${['Final summary','Complete review'].map(x=>`<div class=row><span>☐</span>${x}</div>`).join('')}</section></div>`}async function areaView(rid,aid){let r=await get('reviews',rid);let ars=(await all('areaReviews')).filter(x=>x.reviewId===rid&&x.areaId===aid);let ar=ars[0];if(!ar)return;let responses=(await all('responses')).filter(x=>x.reviewId===rid);let map=Object.fromEntries(responses.map(x=>[x.questionId,x]));let idx=AREAS.findIndex(a=>a[0]===aid);A.innerHTML=`<h1 class=title>Life Area Review</h1><div class=tabs>${AREAS.map((a,i)=>`<button class="${a[0]===aid?'active':''}" data-go="${a[0]}">${String(i+1).padStart(2,'0')}<br><small>${esc(a[1].split(' ')[0])}</small></button>`).join('')}</div><section class=card><div class=sub>${String(idx+1).padStart(2,'0')} OF 12 · CURRENT REALITY</div><h2>${esc(areaName(aid))}</h2><div class=rating>${[1,2,3,4,5,6,7].map(n=>`<button data-rating=${n} class="${ar.rating===n?'active':''}">${n}</button>`).join('')}<span>${ar.rating?ar.rating+' / 7':''}</span></div><label class=q>Current summary</label><textarea id=summary>${esc(ar.summary)}</textarea><div class=sectionTitle>REVIEW QUESTIONS</div>${questions(aid).map(([qid,q])=>{let rec=map[qid];return `<label class=q>${esc(q)}</label><textarea data-qid="${qid}">${esc(rec?.answer||'')}</textarea><button class="btn prev" data-prev="${qid}">Previous answer</button>`}).join('')}<div class=sectionTitle>IMPORTANT PROBLEMS &amp; BOTTLENECKS</div>${hamming().map(([qid,q])=>{let rec=map[qid];return `<label class=q>${esc(q)}</label><textarea data-qid="${qid}">${esc(rec?.answer||'')}</textarea>`}).join('')}<div class=actions><button class=btn id=previous>← Previous</button><button class=btn id=areas>▦ Areas</button><label><input type=checkbox id=reviewed ${ar.completionState==='reviewed'?'checked':''}> Mark reviewed</label><button class="btn primary next" id=next>Next →</button></div></section>`;bindText('#summary','areaReviews',ar,'summary');document.querySelectorAll('[data-rating]').forEach(b=>b.onclick=async()=>{ar.rating=+b.dataset.rating;if(r.status==='draft'){r.status='in_progress';await save('reviews',r)}await save('areaReviews',ar);areaView(rid,aid)});document.querySelectorAll('textarea[data-qid]').forEach(el=>el.addEventListener('input',e=>{let qid=e.target.dataset.qid,rec=map[qid]||{id:uid(),reviewId:rid,areaId:aid,questionId:qid,reviewQuestionKey:rid+':'+qid,questionSetVersion:1,answer:'',notApplicable:false,createdAt:now(),updatedAt:now(),revision:0};rec.answer=e.target.value;map[qid]=rec;debounce('resp'+rec.id,async()=>{if(r.status==='draft'){r.status='in_progress';await save('reviews',r)}await save('responses',rec)})}));document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>location.hash='/review/'+rid+'/area/'+b.dataset.go);document.querySelector('#previous').onclick=()=>location.hash='/review/'+rid+'/area/'+AREAS[Math.max(0,idx-1)][0];document.querySelector('#next').onclick=()=>location.hash='/review/'+rid+'/area/'+AREAS[Math.min(11,idx+1)][0];document.querySelector('#areas').onclick=()=>location.hash='/review';document.querySelector('#reviewed').onchange=async e=>{ar.completionState=e.target.checked?'reviewed':'started';await save('areaReviews',ar)};document.querySelectorAll('.prev').forEach(b=>b.onclick=()=>toast('Previous-answer history becomes active after a prior completed review exists.'))}async function calendar(){let y=new Date().getFullYear();A.innerHTML=`<h1 class=title>Compact Calendar</h1><div class=card><b>${y}</b>${Array.from({length:12},(_,m)=>calendarRow(y,m)).join('')}</div>`}function calendarRow(y,m){let names=['JAN','FEB','MAR','APR','MAY','JUN','JUL','AUG','SEP','OCT','NOV','DEC'];let first=new Date(y,m,1),days=new Date(y,m+1,0).getDate(),off=(first.getDay()+6)%7,cells=Array(off).fill('  ').concat(Array.from({length:days},(_,i)=>String(i+1).padStart(2,' ')));while(cells.length%7)cells.push('  ');let lines=['Mo Tu We Th Fr Sa Su'];for(let i=0;i<cells.length;i+=7)lines.push(cells.slice(i,i+7).join(' '));return `<div class=calendarRow><div class=month>${names[m]}</div><div class=mini>${lines.join('\n')}</div><textarea class=monthNote placeholder="Monthly notes"></textarea></div>`}async function history(){let rs=(await all('reviews')).sort((a,b)=>b.referenceDate.localeCompare(a.referenceDate));A.innerHTML=`<h1 class=title>Review history</h1><div class="card history">${rs.length?rs.map(r=>`<div class=row><span>${esc(r.referenceDate)} · <b>${esc(r.title)}</b></span><span class=pill>${esc(r.status)}</span></div>`).join(''):'No reviews yet.'}</div>`}async function placeholder(name){A.innerHTML=`<h1 class=title>${name}</h1><div class=card><p>This V1.0 foundation build intentionally validates the Review Core first.</p><p class=muted>${name} is reserved for the next implementation phase after persistence testing passes.</p></div>`}async function systemCheck(){let h=await health();A.innerHTML=`<h1 class=title>System Check</h1><div class="card sys">App version: 1.0.0<br>Database: ${h.name}<br>Database version: ${h.version}<br>Expected stores: ${h.stores}<br>Missing stores: ${h.missing.length?h.missing.join(', '):'None'}<br>IndexedDB: OK<br>Question Set: V1</div><p><a class=btn href="#/home">Back</a></p>`}function toast(x){let t=document.createElement('div');t.className='toast';t.textContent=x;document.body.append(t);setTimeout(()=>t.remove(),2500)}async function render(){try{await openDB();let r=route(),m=r.match(/^\/review\/([^/]+)\/area\/([^/]+)/);if(m)return areaView(m[1],m[2]);if(r==='/home')return home();if(r==='/review'||r.startsWith('/review/'))return reviewLanding();if(r.startsWith('/calendar'))return calendar();if(r==='/history')return history();if(r==='/settings/system')return systemCheck();if(r==='/plan')return placeholder('Plan');return home()}catch(e){A.innerHTML=`<h1 class=title>Startup problem</h1><div class=card><b>8760 HOURS could not complete startup.</b><p class=danger>${esc(e.message)}</p><button class=btn onclick="location.reload()">Retry</button></div>`}}window.addEventListener('hashchange',render);render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./service-worker.js').catch(()=>{});'''
manifest='''{"name":"8760 HOURS","short_name":"8760 HOURS","description":"A private life review and year planning app.","start_url":"./","scope":"./","display":"standalone","background_color":"#f4f6f8","theme_color":"#123b6d","icons":[{"src":"icons/icon-192.png","sizes":"192x192","type":"image/png"},{"src":"icons/icon-512.png","sizes":"512x512","type":"image/png"}]}'''
sw=r'''const CACHE='8760-hours-v1.0.0-foundation';const SHELL=['./','./index.html','./styles-v100.css','./app-v100.js','./hours-db-v100.js','./question-set-v1.js','./manifest.webmanifest','./offline.html','./icons/icon-192.png','./icons/icon-512.png'];self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(SHELL))));self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(ks=>Promise.all(ks.filter(k=>k.startsWith('8760-hours-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));self.addEventListener('fetch',e=>{if(e.request.mode==='navigate'){e.respondWith(fetch(e.request).then(r=>{let x=r.clone();caches.open(CACHE).then(c=>c.put('./index.html',x));return r}).catch(()=>caches.match('./index.html').then(r=>r||caches.match('./offline.html'))));return}e.respondWith(caches.match(e.request).then(r=>r||fetch(e.request)))})'''
off='''<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>8760 HOURS Offline</title><style>body{font-family:system-ui;padding:30px;color:#123b6d}</style><h1>8760 HOURS</h1><p>The application shell is not available yet. Reconnect once and reload.</p>'''
for n,s in [('index.html',html),('styles-v100.css',css),('hours-db-v100.js',db),('question-set-v1.js',qs),('app-v100.js',app),('manifest.webmanifest',manifest),('service-worker.js',sw),('offline.html',off)]: (p/n).write_text(s)
